CREATE OR REPLACE FUNCTION public.cig_item_remaining(p_item_id uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT COALESCE((SELECT quantity FROM public.cig_items WHERE id = p_item_id), 0) + COALESCE((SELECT SUM(quantity) FROM public.cig_purchases WHERE item_id = p_item_id), 0) - COALESCE((SELECT SUM(quantity) FROM public.cig_transfers WHERE item_id = p_item_id), 0) $$;
CREATE OR REPLACE FUNCTION public.cig_mardooda_balance() RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT COALESCE((SELECT SUM(quantity * wholesale_price) FROM public.cig_transfers), 0) - COALESCE((SELECT SUM(quantity * wholesale_price) FROM public.cig_purchases), 0) - COALESCE((SELECT SUM(amount) FROM public.cig_settlements), 0) $$;
CREATE OR REPLACE FUNCTION public.cig_add_item(p_name text, p_quantity numeric, p_wholesale_price numeric) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_name text := btrim(coalesce(p_name, '')); v_id uuid; BEGIN IF v_name = '' THEN RAISE EXCEPTION 'اكتب اسم الصنف'; END IF; IF p_quantity IS NULL OR p_quantity < 0 THEN RAISE EXCEPTION 'الكمية غير صحيحة'; END IF; IF p_wholesale_price IS NULL OR p_wholesale_price < 0 THEN RAISE EXCEPTION 'السعر غير صحيح'; END IF; IF EXISTS (SELECT 1 FROM public.cig_items WHERE lower(name) = lower(v_name)) THEN RAISE EXCEPTION 'الصنف موجود بالفعل في المخزن - عدله بدل إضافة صنف جديد'; END IF; INSERT INTO public.cig_items (name, quantity, wholesale_price) VALUES (v_name, p_quantity, p_wholesale_price) RETURNING id INTO v_id; RETURN v_id; END $$;
CREATE OR REPLACE FUNCTION public.cig_update_item(p_item_id uuid, p_name text, p_quantity numeric, p_wholesale_price numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_name text := btrim(coalesce(p_name, '')); BEGIN IF v_name = '' THEN RAISE EXCEPTION 'اكتب اسم الصنف'; END IF; IF p_quantity IS NULL OR p_quantity < 0 THEN RAISE EXCEPTION 'الكمية غير صحيحة'; END IF; IF p_wholesale_price IS NULL OR p_wholesale_price < 0 THEN RAISE EXCEPTION 'السعر غير صحيح'; END IF; IF EXISTS (SELECT 1 FROM public.cig_items WHERE lower(name) = lower(v_name) AND id <> p_item_id) THEN RAISE EXCEPTION 'يوجد صنف آخر بنفس الاسم'; END IF; UPDATE public.cig_items SET name = v_name, quantity = p_quantity, wholesale_price = p_wholesale_price WHERE id = p_item_id; IF NOT FOUND THEN RAISE EXCEPTION 'الصنف غير موجود'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.cig_delete_item(p_item_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF EXISTS (SELECT 1 FROM public.cig_transfers WHERE item_id = p_item_id) OR EXISTS (SELECT 1 FROM public.cig_purchases WHERE item_id = p_item_id) THEN RAISE EXCEPTION 'لا يمكن حذف صنف له عمليات نقل أو شراء سابقة'; END IF; DELETE FROM public.cig_items WHERE id = p_item_id; IF NOT FOUND THEN RAISE EXCEPTION 'الصنف غير موجود'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.cig_transfer(p_item_id uuid, p_quantity numeric, p_transfer_date date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_name text; v_price numeric; v_rem numeric; BEGIN IF p_quantity IS NULL OR p_quantity <= 0 THEN RAISE EXCEPTION 'اكتب كمية أكبر من صفر'; END IF; SELECT name, wholesale_price INTO v_name, v_price FROM public.cig_items WHERE id = p_item_id; IF v_name IS NULL THEN RAISE EXCEPTION 'الصنف غير موجود'; END IF; v_rem := public.cig_item_remaining(p_item_id); IF p_quantity > v_rem THEN RAISE EXCEPTION 'الكمية المتاحة في المخزن (%) لا تكفي لنقل (%)', v_rem, p_quantity; END IF; INSERT INTO public.cig_transfers (item_id, item_name, quantity, wholesale_price, transfer_date) VALUES (p_item_id, v_name, p_quantity, v_price, COALESCE(p_transfer_date, current_date)); END $$;
CREATE OR REPLACE FUNCTION public.cig_update_transfer(p_id uuid, p_quantity numeric, p_transfer_date date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_item uuid; v_rem numeric; BEGIN IF p_quantity IS NULL OR p_quantity <= 0 THEN RAISE EXCEPTION 'اكتب كمية أكبر من صفر'; END IF; SELECT item_id INTO v_item FROM public.cig_transfers WHERE id = p_id; IF v_item IS NULL THEN RAISE EXCEPTION 'العملية غير موجودة'; END IF; v_rem := COALESCE((SELECT quantity FROM public.cig_items WHERE id = v_item), 0) + COALESCE((SELECT SUM(quantity) FROM public.cig_purchases WHERE item_id = v_item), 0) - COALESCE((SELECT SUM(quantity) FROM public.cig_transfers WHERE item_id = v_item AND id <> p_id), 0); IF p_quantity > v_rem THEN RAISE EXCEPTION 'الكمية المتاحة في المخزن (%) لا تكفي (%)', v_rem, p_quantity; END IF; UPDATE public.cig_transfers SET quantity = p_quantity, transfer_date = COALESCE(p_transfer_date, transfer_date) WHERE id = p_id; END $$;
CREATE OR REPLACE FUNCTION public.cig_delete_transfer(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN DELETE FROM public.cig_transfers WHERE id = p_id; IF NOT FOUND THEN RAISE EXCEPTION 'العملية غير موجودة'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.cig_purchase(p_item_id uuid, p_name text, p_quantity numeric, p_wholesale_price numeric, p_purchase_date date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_id uuid; v_name text; v_bal numeric; v_val numeric; BEGIN IF p_quantity IS NULL OR p_quantity <= 0 THEN RAISE EXCEPTION 'اكتب كمية أكبر من صفر'; END IF; IF p_wholesale_price IS NULL OR p_wholesale_price < 0 THEN RAISE EXCEPTION 'السعر غير صحيح'; END IF; v_val := p_quantity * p_wholesale_price; v_bal := public.cig_mardooda_balance(); IF v_val > v_bal + 0.005 THEN RAISE EXCEPTION 'رصيد فلوس مردودة غير كافٍ: الرصيد الحالي (%) والمطلوب (%)', v_bal, v_val; END IF; IF p_item_id IS NOT NULL THEN SELECT name INTO v_name FROM public.cig_items WHERE id = p_item_id; IF v_name IS NULL THEN RAISE EXCEPTION 'الصنف غير موجود'; END IF; v_id := p_item_id; ELSE v_name := btrim(coalesce(p_name, '')); IF v_name = '' THEN RAISE EXCEPTION 'اكتب اسم الصنف'; END IF; SELECT id INTO v_id FROM public.cig_items WHERE lower(name) = lower(v_name); IF v_id IS NULL THEN INSERT INTO public.cig_items (name, quantity, wholesale_price) VALUES (v_name, 0, p_wholesale_price) RETURNING id INTO v_id; END IF; END IF; INSERT INTO public.cig_purchases (item_id, item_name, quantity, wholesale_price, purchase_date) VALUES (v_id, v_name, p_quantity, p_wholesale_price, COALESCE(p_purchase_date, current_date)); END $$;
CREATE OR REPLACE FUNCTION public.cig_update_purchase(p_id uuid, p_quantity numeric, p_wholesale_price numeric, p_purchase_date date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_bal numeric; v_val numeric; BEGIN IF p_quantity IS NULL OR p_quantity <= 0 THEN RAISE EXCEPTION 'اكتب كمية أكبر من صفر'; END IF; IF p_wholesale_price IS NULL OR p_wholesale_price < 0 THEN RAISE EXCEPTION 'السعر غير صحيح'; END IF; v_val := p_quantity * p_wholesale_price; v_bal := COALESCE((SELECT SUM(quantity * wholesale_price) FROM public.cig_transfers), 0) - COALESCE((SELECT SUM(quantity * wholesale_price) FROM public.cig_purchases WHERE id <> p_id), 0) - COALESCE((SELECT SUM(amount) FROM public.cig_settlements), 0); IF v_val > v_bal + 0.005 THEN RAISE EXCEPTION 'رصيد فلوس مردودة غير كافٍ: الرصيد الحالي (%) والمطلوب (%)', v_bal, v_val; END IF; UPDATE public.cig_purchases SET quantity = p_quantity, wholesale_price = p_wholesale_price, purchase_date = COALESCE(p_purchase_date, purchase_date) WHERE id = p_id; IF NOT FOUND THEN RAISE EXCEPTION 'العملية غير موجودة'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.cig_delete_purchase(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN DELETE FROM public.cig_purchases WHERE id = p_id; IF NOT FOUND THEN RAISE EXCEPTION 'العملية غير موجودة'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.cig_add_settlement(p_amount numeric, p_note text, p_settlement_date date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_bal numeric; BEGIN IF p_amount IS NULL OR p_amount <= 0 THEN RAISE EXCEPTION 'اكتب مبلغاً أكبر من صفر'; END IF; v_bal := public.cig_mardooda_balance(); IF p_amount > v_bal + 0.005 THEN RAISE EXCEPTION 'رصيد فلوس مردودة غير كافٍ: الرصيد الحالي (%) والمطلوب (%)', v_bal, p_amount; END IF; INSERT INTO public.cig_settlements (settlement_date, amount, note) VALUES (COALESCE(p_settlement_date, current_date), p_amount, nullif(btrim(coalesce(p_note, '')), '')); END $$;
CREATE OR REPLACE FUNCTION public.cig_delete_settlement(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN DELETE FROM public.cig_settlements WHERE id = p_id; IF NOT FOUND THEN RAISE EXCEPTION 'العملية غير موجودة'; END IF; END $$;
GRANT EXECUTE ON FUNCTION public.cig_item_remaining(uuid), public.cig_mardooda_balance(), public.cig_add_item(text, numeric, numeric), public.cig_update_item(uuid, text, numeric, numeric), public.cig_delete_item(uuid), public.cig_transfer(uuid, numeric, date), public.cig_update_transfer(uuid, numeric, date), public.cig_delete_transfer(uuid), public.cig_purchase(uuid, text, numeric, numeric, date), public.cig_update_purchase(uuid, numeric, numeric, date), public.cig_delete_purchase(uuid), public.cig_add_settlement(numeric, text, date), public.cig_delete_settlement(uuid) TO anon, authenticated, service_role;